-- Generated by AutomateDV (formerly known as dbtvault)

    

WITH source_data AS (
    SELECT a.HK_LISTING, a.HD_LISTING_ATTRS, a.category, a.deal_type, a.property_type, a.rooms, a.area_total_m2, a.area_living_m2, a.area_kitchen_m2, a.floor, a.floors_total, a.building_type, a.build_year, a.ceiling_height_m, a.bathroom, a.furniture, a.renovation, a.balcony, a.parking, a.complex_name, a.seller_type, a.district_name, a.description_hash, a.LOAD_DATETIME, a.RECORD_SOURCE
    FROM "krisha_dwh"."marts_dv"."stg_dv_listings" AS a
    WHERE a.HK_LISTING IS NOT NULL
),

latest_records AS (
    SELECT b.HK_LISTING, b.HD_LISTING_ATTRS, b.LOAD_DATETIME
    FROM (
        SELECT current_records.HK_LISTING, current_records.HD_LISTING_ATTRS, current_records.LOAD_DATETIME,
            ROW_NUMBER() OVER (
               PARTITION BY current_records.HK_LISTING
               ORDER BY current_records.LOAD_DATETIME DESC
            ) AS rank
        FROM "krisha_dwh"."marts_dv"."sat_listing_attributes" AS current_records
            JOIN (
                SELECT DISTINCT source_data.HK_LISTING
                FROM source_data
            ) AS source_records
                ON source_records.HK_LISTING = current_records.HK_LISTING
    ) AS b
    WHERE b.rank = 1
),

unique_source_records AS (
    SELECT
        b.HK_LISTING, b.HD_LISTING_ATTRS, b.category, b.deal_type, b.property_type, b.rooms, b.area_total_m2, b.area_living_m2, b.area_kitchen_m2, b.floor, b.floors_total, b.building_type, b.build_year, b.ceiling_height_m, b.bathroom, b.furniture, b.renovation, b.balcony, b.parking, b.complex_name, b.seller_type, b.district_name, b.description_hash, b.LOAD_DATETIME, b.RECORD_SOURCE
    FROM (
        SELECT
            sd.HK_LISTING, sd.HD_LISTING_ATTRS, sd.category, sd.deal_type, sd.property_type, sd.rooms, sd.area_total_m2, sd.area_living_m2, sd.area_kitchen_m2, sd.floor, sd.floors_total, sd.building_type, sd.build_year, sd.ceiling_height_m, sd.bathroom, sd.furniture, sd.renovation, sd.balcony, sd.parking, sd.complex_name, sd.seller_type, sd.district_name, sd.description_hash, sd.LOAD_DATETIME, sd.RECORD_SOURCE,
            LAG(
                sd.HD_LISTING_ATTRS,
                1,
                COALESCE(lr.HD_LISTING_ATTRS,
                         CAST('FFFFFFFF' AS BYTEA))
            ) OVER (
                PARTITION BY sd.HK_LISTING
                ORDER BY sd.LOAD_DATETIME ASC
            ) AS prev_hashdiff
        FROM source_data AS sd
        LEFT OUTER JOIN latest_records AS lr
            ON sd.HK_LISTING = lr.HK_LISTING
        ) AS b
    WHERE b.HD_LISTING_ATTRS != b.prev_hashdiff
),

records_to_insert AS (
    SELECT usr.HK_LISTING, usr.HD_LISTING_ATTRS, usr.category, usr.deal_type, usr.property_type, usr.rooms, usr.area_total_m2, usr.area_living_m2, usr.area_kitchen_m2, usr.floor, usr.floors_total, usr.building_type, usr.build_year, usr.ceiling_height_m, usr.bathroom, usr.furniture, usr.renovation, usr.balcony, usr.parking, usr.complex_name, usr.seller_type, usr.district_name, usr.description_hash, usr.LOAD_DATETIME, usr.RECORD_SOURCE
    FROM unique_source_records AS usr
)

SELECT * FROM records_to_insert